import os
from datetime import date
import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30

# Supply the equipment records to evaluate before running the script.
equipment_records = [
    {
        "equipmentId": os.environ.get("EQUIPMENT_ID", ""),
        "industryId": os.environ.get("INDUSTRY_ID", ""),
        "usageDetails": os.environ.get("USAGE_DETAILS", ""),
    }
]

session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})

# Retrieve the maintenance schedule for all facilities.
schedule_response = session.get(
    f"{BASE_URL}/maintenance/schedules",
    timeout=TIMEOUT,
)
schedule_response.raise_for_status()
schedule_data = schedule_response.json()

# Submit usage details for industrial equipment efficiency evaluation.
efficiency_results = []
for equipment in equipment_records:
    if not all(equipment.values()):
        continue

    response = session.post(
        f"{BASE_URL}/equipment/efficiency-evaluation",
        json=equipment,
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    efficiency_results.append(response.json())

# Provide feedback based on checks possible from the returned schedule data.
# The available schedule fields support validating dates and activity types, but
# do not provide actual-versus-reported maintenance data for accuracy comparison.
activities = (
    schedule_data
    if isinstance(schedule_data, list)
    else schedule_data.get("items", schedule_data.get("activities", []))
)
if not isinstance(activities, list):
    activities = []

feedback = []
today = date.today()

for index, activity in enumerate(activities):
    if not isinstance(activity, dict):
        feedback.append(
            {
                "activity": index,
                "feedback": "Schedule entry is not an object; verify the generated report data.",
            }
        )
        continue

    activity_feedback = []
    scheduled_date = activity.get("date")
    activity_type = activity.get("type")

    if not scheduled_date:
        activity_feedback.append("Scheduled date is missing; add a date to improve report completeness.")
    else:
        try:
            parsed_date = date.fromisoformat(scheduled_date[:10])
            if parsed_date < today:
                activity_feedback.append(
                    "Scheduled date has passed; confirm whether the maintenance was completed "
                    "or reschedule it."
                )
        except (TypeError, ValueError):
            activity_feedback.append("Scheduled date is invalid; use YYYY-MM-DD format.")

    if not activity_type:
        activity_feedback.append("Maintenance type is missing; specify the planned activity.")

    if activity_feedback:
        feedback.append({"activity": index, "feedback": activity_feedback})

result = {
    "maintenance_schedule": schedule_data,
    "efficiency_evaluations": efficiency_results,
    "maintenance_report_feedback": feedback,
}
print(result)

