import os
import requests

BASE_URL = "https://api.socbench.example"
PROJECT_ID = os.environ["PROJECT_ID"]

response = requests.get(
    f"{BASE_URL}/projects/{PROJECT_ID}/materials",
    headers={"Accept": "application/json"},
    timeout=30,
)
response.raise_for_status()
materials = response.json()

def recommend_improvements(material):
    properties = material.get("properties") or {}
    details = " ".join(
        str(value) for value in properties.values()
    ).lower()
    classification = str(material.get("classification", "")).lower()

    recommendations = []
    if any(term in details for term in ("contaminat", "mixed", "coated", "treated")):
        recommendations.append(
            "Separate the material from contaminants and incompatible materials before recycling."
        )
    if any(term in details for term in ("adhesive", "laminated", "composite")):
        recommendations.append(
            "Avoid bonded or composite constructions where possible; use separable, single-material components."
        )
    if classification and any(
        term in classification for term in ("non-recyclable", "not recyclable", "low")
    ):
        recommendations.append(
            "Consider replacing it with a locally recyclable alternative or a reusable material."
        )
    if not recommendations:
        recommendations.append(
            "Keep the material clean and sorted by type, and verify that its coatings and additives are compatible with local recycling."
        )
    return recommendations

material_names = [
    material.get("materialName")
    for material in materials
    if material.get("materialName")
]

result = {
    "projectId": PROJECT_ID,
    "materials": materials,
    "recyclabilityRecommendations": [
        {
            "materialName": material.get("materialName", "Unknown material"),
            "recommendations": recommend_improvements(material),
        }
        for material in materials
    ],
    "proposedRecycler": {
        "recyclerName": os.getenv(
            "RECYCLER_NAME", "Candidate Construction Materials Recycler"
        ),
        "location": os.getenv(
            "RECYCLER_LOCATION", "Location to be confirmed"
        ),
        "materialsAccepted": material_names,
    },
}

print(result)

