def normalize(value):
    return re.sub(r"\s+", " ", str(value)).strip().casefold()


def find_food_values(data):
    """Extract food names from common allergen-response field names."""
    foods = []

    if isinstance(data, dict):
        for key, value in data.items():
            if key.casefold() in {"food", "foods", "fooditem", "fooditems", "items", "products"}:
                if isinstance(value, list):
                    foods.extend(str(item) for item in value if isinstance(item, (str, int, float)))
                elif isinstance(value, (str, int, float)):
                    foods.append(str(value))
            else:
                foods.extend(find_food_values(value))
    elif isinstance(data, list):
        for item in data:
            foods.extend(find_food_values(item))

    return foods


def find_allergen_entries(data):
    if isinstance(data, list):
        return [entry for entry in data if isinstance(entry, dict)]
    if isinstance(data, dict):
        for value in data.values():
            if isinstance(value, list):
                entries = [entry for entry in value if isinstance(entry, dict)]
                if entries:
                    return entries
    return []


