import json
import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30


def get_json(path):
    response = requests.get(f"{BASE_URL}{path}", timeout=TIMEOUT)
    response.raise_for_status()
    try:
        return response.json()
    except ValueError:
        return response.text


def walk(value):
    if isinstance(value, dict):
        yield value
        for child in value.values():
            yield from walk(child)
    elif isinstance(value, list):
        for child in value:
            yield from walk(child)


inventory = get_json("/inventory/status")
supply_chain_overview = get_json("/supplychain/overview")

insufficient_items = []
seen = set()

for record in walk(inventory):
    item_id = next(
        (record[key] for key in ("itemId", "id", "sku") if key in record),
        None,
    )
    quantity = next(
        (
            record[key]
            for key in ("quantity", "stock", "currentQuantity", "availableQuantity")
            if isinstance(record.get(key), (int, float))
        ),
        None,
    )
    predicted = record.get("predictedQuantity")

    is_insufficient = (
        isinstance(quantity, (int, float))
        and (
            (isinstance(predicted, (int, float)) and quantity < predicted)
            or (not isinstance(predicted, (int, float)) and quantity <= 0)
        )
    )

    if is_insufficient:
        identity = str(item_id) if item_id is not None else json.dumps(record, sort_keys=True)
        if identity not in seen:
            seen.add(identity)
            insufficient_items.append(record)

