inventory = get_json("/inventory")
alerts = get_json("/alerts")

inventory_by_id = {item.get("item_id"): item for item in inventory if item.get("item_id")}
inventory_by_name = {
    item.get("name", "").casefold(): item
    for item in inventory
    if item.get("name")
}

