import json
import os
from datetime import date

import requests

BASE_URL = "https://api.socbench.example"
PROPERTY_PRICE_USD = float(os.getenv("PROPERTY_PRICE_USD", "0"))
LOAN_TENURE_YEARS = float(os.getenv("LOAN_TENURE_YEARS", "30"))

search_criteria = {
    "location": "Chicago",
    "propertyType": "residential",
}
with open("saved_search_criteria.json", "w", encoding="utf-8") as file:
    json.dump(search_criteria, file, indent=2)

session = requests.Session()
session.headers.update({"Accept": "application/json"})

agents_response = session.get(
    f"{BASE_URL}/recommendations",
    params={"property": "Residential property in Chicago"},
    timeout=30,
)
agents_response.raise_for_status()
recommended_agents = agents_response.json()

down_payment_response = session.get(
    f"{BASE_URL}/down-payment-summary",
    timeout=30,
)
down_payment_response.raise_for_status()
down_payment_details = down_payment_response.json()

rates_response = session.get(
    f"{BASE_URL}/interest-rates",
    timeout=30,
)
rates_response.raise_for_status()
rates_data = rates_response.json()


def find_rate_records(data):
    records = []
    if isinstance(data, dict):
        if "rate" in data:
            records.append(data)
        for value in data.values():
            records.extend(find_rate_records(value))
    elif isinstance(data, list):
        for item in data:
            records.extend(find_rate_records(item))
    return records


def monthly_payment(principal, annual_rate_percent, years):
    months = int(years * 12)
    monthly_rate = annual_rate_percent / 100 / 12
    if months <= 0:
        raise ValueError("Loan tenure must be greater than zero.")
    if monthly_rate == 0:
        return principal / months
    return principal * monthly_rate / (1 - (1 + monthly_rate) ** -months)


rate_records = find_rate_records(rates_data)
dated_rates = [
    record
    for record in rate_records
    if isinstance(record.get("rate"), (int, float))
]
dated_rates.sort(key=lambda record: record.get("date", ""))

today = date.today().isoformat()
current_candidates = [
    record for record in dated_rates if record.get("date", "") <= today
]
current_rate = (
    float(current_candidates[-1]["rate"])
    if current_candidates
    else (float(dated_rates[-1]["rate"]) if dated_rates else None)
)

down_payment_amount = down_payment_details.get("recommendedDownPayment")
if down_payment_amount is None:
    down_payment_amount = down_payment_details.get("minimumDownPayment")

loan_analysis = {
    "propertyPriceUSD": PROPERTY_PRICE_USD or None,
    "downPaymentDetails": down_payment_details,
    "loanTenureYears": LOAN_TENURE_YEARS,
    "interestRateComparisons": [],
}

if PROPERTY_PRICE_USD > 0 and down_payment_amount is not None:
    loan_amount = max(0.0, PROPERTY_PRICE_USD - float(down_payment_amount))
    loan_analysis["loanAmountUSD"] = loan_amount

    if current_rate is not None:
        loan_analysis["currentRatePercent"] = current_rate
        loan_analysis["estimatedMonthlyPaymentUSD"] = monthly_payment(
            loan_amount, current_rate, LOAN_TENURE_YEARS
        )

    for record in dated_rates:
        rate = float(record["rate"])
        loan_analysis["interestRateComparisons"].append(
            {
                "date": record.get("date"),
                "ratePercent": rate,
                "estimatedMonthlyPaymentUSD": monthly_payment(
                    loan_amount, rate, LOAN_TENURE_YEARS
                ),
            }
        )

result = {
    "recommendedAgents": recommended_agents,
    "savedSearchCriteria": search_criteria,
    "loanAnalysis": loan_analysis,
    "downPaymentDetails": down_payment_details,
    "interestRates": rates_data,
}
print(json.dumps(result, indent=2, default=str))
